function heartFractal() {
  let offset = 0;
  for (let i = 0; i < 360; i += 1) {
    let r = sin(i * 0.01) * 100 + 50;
    let z = cos(i * 0.01) * 50 + 50;
    let x = cos(i) * r;
    let y = sin(i) * r;
    let color = color(255, 0, 0, 128);
    addPoint(x, y, z, color);
    offset += octavesize;
    if (i % 30 == 0) {
      octavesize += 0.1;
      octavescale *= 0.9;
    }
  }
  for (let i = 0; i < pointbuffer.length; i++) {
    let vertex = pointbuffer[i];
    let x = vertex.x;
    let y = vertex.y;
    let z = vertex.z;
    let color = vertex.color;
    fill(color);
    beginShape(QUADS);
    vertexAttribPointer(0, x, y, z);
    vertexAttribPointer(1, x + 1, y, z);
    vertexAttribPointer(2, x, y + 1, z);
    vertexAttribPointer(3, x + 1, y + 1, z);
    endShape();
  }
}

function addPoint(x, y, z, color) {
  pointbuffer.push({
    x: x,
    y: y,
    z: z,
    color: color
  });
}

function getVertexAtts(i) {
  let vertex = pointbuffer[i];
  return [
    vertex.x,
    vertex.y,
    vertex.z,
    vertex.color
  ];
}
